import argparse
import os
import webbrowser
from typing import List, Optional, Text
from urllib.parse import urlencode

from rasa import telemetry
from rasa.cli import SubParsersAction
from rasa.cli.arguments import shell as arguments
from rasa.cli.arguments.default_arguments import add_sub_agents_param
from rasa.cli.project_env import resolve_project_dir
from rasa.core.config.channel_loading import resolve_channels_config
from rasa.core.config.configuration import Configuration
from rasa.exceptions import ModelNotFound
from rasa.model import get_local_artifact_metadata
from rasa.shared.constants import (
    DOCS_URL_INSPECTOR,
    LEGACY_INSPECTOR_REMOVAL_VERSION,
)
from rasa.shared.exceptions import RasaException
from rasa.shared.utils.cli import print_error
from rasa.shared.utils.io import raise_deprecation_warning
from rasa.utils.cli import remove_argument_from_parser


def warn_legacy_inspector_deprecated() -> None:
    """Warn that the legacy Inspector UI is on its way out."""
    # The `docs` argument of `raise_deprecation_warning` is never rendered -- it
    # always sets `stacklevel`, which makes `raise_warning` print the source line
    # instead. Hence the URL in the message. `stacklevel=4` walks past this helper
    # so the reported frame is the CLI entrypoint rather than the line below.
    raise_deprecation_warning(
        "The legacy Inspector UI (`--legacy`) is deprecated. `rasa inspect` and "
        "`rasa run --inspect` already open the current Inspector, so drop "
        "`--legacy` (and `--voice`, which only exists alongside it) to use it. "
        f"See {DOCS_URL_INSPECTOR}.",
        warn_until_version=LEGACY_INSPECTOR_REMOVAL_VERSION,
        stacklevel=4,
    )


def add_subparser(
    subparsers: SubParsersAction, parents: List[argparse.ArgumentParser]
) -> None:
    """Add all inspect parsers.

    Args:
        subparsers: subparser we are going to attach to
        parents: Parent parsers, needed to ensure tree structure in argparse
    """
    inspect_parser = subparsers.add_parser(
        "inspect",
        parents=parents,
        conflict_handler="resolve",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
        help=(
            "Loads your trained model and lets you talk to your "
            "assistant in the browser."
        ),
    )
    inspect_parser.set_defaults(func=inspect)
    arguments.set_shell_arguments(inspect_parser)

    # additional argument for voice (only applicable with --legacy)
    inspect_parser.add_argument(
        "--voice",
        help=(
            "Deprecated. Enable voice (only applicable with --legacy). The "
            "current Inspector offers Voice from the chat input instead."
        ),
        action="store_true",
        default=False,
    )
    inspect_parser.add_argument(
        "--legacy",
        help=(
            "Deprecated, will be removed in "
            f"{LEGACY_INSPECTOR_REMOVAL_VERSION}. Use the legacy inspector UI "
            "(socketio-based)."
        ),
        action="store_true",
        default=False,
    )

    add_sub_agents_param(inspect_parser)

    # it'd be confusing to expose those arguments to the user,
    # so we remove them
    remove_argument_from_parser(inspect_parser, "--credentials")
    remove_argument_from_parser(inspect_parser, "--connector")
    remove_argument_from_parser(inspect_parser, "--enable-api")


async def open_inspector_in_browser(
    server_url: Text,
    legacy: bool = False,
    voice: bool = False,
    token: Optional[Text] = None,
) -> None:
    """Opens the rasa inspector in the default browser."""
    dev_port = os.environ.get("RASA_INSPECTOR_DEV_PORT")
    query_params: dict = {"projectUrl": server_url}
    if token:
        query_params["token"] = token
    query_string = f"?{urlencode(query_params)}"

    if dev_port:
        webbrowser.open(f"http://localhost:{dev_port}{query_string}")
    elif legacy and voice:
        webbrowser.open(
            f"{server_url}/webhooks/browser_audio/inspect.html{query_string}"
        )
    elif legacy:
        webbrowser.open(f"{server_url}/webhooks/socketio/inspect.html{query_string}")
    else:
        webbrowser.open(f"{server_url}/webhooks/inspector/inspect.html{query_string}")


def inspect(args: argparse.Namespace) -> None:
    """Inspect the bot using the most recent model."""
    if args.voice and not args.legacy:
        raise RasaException(
            "The --voice flag is no longer needed. "
            "Run rasa inspect and switch to Voice from the chat input"
        )

    import rasa.cli.run
    from rasa.cli.validation.config_path_validation import get_validated_path
    from rasa.shared.constants import DEFAULT_MODELS_PATH

    # the following arguments are not exposed to the user
    if args.voice and args.legacy:
        args.connector = "browser_audio"
    elif args.legacy:
        args.connector = "socketio"
    else:
        args.connector = "inspector"
    args.enable_api = True
    args.inspect = True
    args.credentials = None
    args.open_inspector_in_browser = True
    dev_port = os.environ.get("RASA_INSPECTOR_DEV_PORT")
    if dev_port:
        inspector_frontend_url = f"http://localhost:{dev_port}"
        if args.cors:
            args.cors.append(inspector_frontend_url)
        else:
            args.cors = [inspector_frontend_url]

    model = get_validated_path(args.model, "model", DEFAULT_MODELS_PATH)

    # A missing model returns before ``rasa run``, which loads endpoints.
    # Sub-agents still have to be loaded on that path.
    Configuration.initialise_sub_agents(args.sub_agents)

    try:
        model, metadata = get_local_artifact_metadata(model)
    except ModelNotFound:
        print_error(
            "No model found. Train a model before running the "
            "server using `rasa train`."
        )
        return

    # Same channel choice as the server, including a Mantle archive whose
    # skills are not on disk, so an inspector server_url override is seen.
    credentials = resolve_channels_config(
        model_path=model,
        project_root=resolve_project_dir(),
    )
    args.inspector_server_url = (
        (credentials.channels.get("inspector") or {}).get("server_url")
        if credentials
        else None
    )

    telemetry.track_inspect_started(args.connector, metadata.assistant_id)
    rasa.cli.run.run(args)
